def split_counts(grid, sep):
    rows=[i for i,r in enumerate(grid) if all(v==sep for v in r)]
    cols=[j for j in range(len(grid[0])) if all(r[j]==sep for r in grid)]
    def runs(n, seps):
        out=[];s=0
        for i in sorted(list(seps)+[n]):
            if i>s: out.append((s,i))
            s=i+1
        return out
    return runs(len(grid),rows), runs(len(grid[0]),cols)

def transform(grid, sep=3, target=5, one=3, multi=1):
    rr,cc=split_counts(grid,sep)
    return [[one if sum(grid[i][j]==target for i in range(r0,r1) for j in range(c0,c1))==1 else (multi if any(grid[i][j]==target for i in range(r0,r1) for j in range(c0,c1)) else 0) for (c0,c1) in cc] for (r0,r1) in rr]

